    const startLoading = (txt = '') => {
        if (txt) {
            loadingTxt.value = txt
            hasTxt.value = true
        } else {
            loadingTxt.value = ''
            hasTxt.value = false
        }

        isLoading.value = true
    }

    const stopLoading = () => {
        isLoading.value = false
    }

    return {
        isLoading,
        loadingTxt,
        hasTxt,
        timeoutMs,
