 */
export const pickServiceRows = (body, serviceMenu) => {
    const rows = toAppArray(body);
    if (serviceMenu === 'all') return rows;

    const serviceCode = serviceMenu === 'workTools' ? 'multiModal' : serviceMenu;
    return rows.filter((row) => String(row?.serviceCode || '') === serviceCode);
};

/** 행 목록에서 appList 만 평탄화해서 추출 */
export const flattenAppList = (rows) => {
    return toAppArray(rows).flatMap((row) => toAppArray(row?.appList));
};

// 앱 정보 찾기
export const findAppInfo = (appList, appId, mode, serviceMenu) => {
    const list = toAppArray(appList);

    if (serviceMenu === 'workTools') {
        const modeLower = String(mode ?? '').toLowerCase();
        if (!modeLower) return undefined;
        return list.find((item) => {
            const itemMode = String(item?.mode || '').toLowerCase();
            return itemMode === modeLower;
        });
    }

    const targetAppId = String(appId ?? '');
    if (!targetAppId) return undefined;
    return list.find((item) => {
        const itemAppId = String(item?.app_id || '');
        return itemAppId === targetAppId;
    });
};

