import { readUser } from '@/storage/userStorage.js'
import { updateLogAndGo } from '@/utils/appUpdateLog.js'
import { inf } from '@/api/interface.js'
import { isSuccess, toast } from '@/utils/common.js'
import { writeOpenAppDoc } from '@/storage/useOpenAppStroage.js'

/**
 * @param {import('vue-router').Router} router - Vue Router 인스턴스
 * @returns {{ goToApp: Function }}
 */
export function useAppNavigation(router) {

  /**
   * 앱으로 이동 (공통)
   * - simple mode: 임베딩 확인 후 writeOpenAppDoc 처리
   * - img mode: extraQuery 주입
   * @param {Object} item - 앱/에이전트 아이템
   * @param {Function} [afterGo] - 이동 후 실행할 콜백
   */
  const goToApp = async (item, afterGo) => {
    if (!item) return
    const raw = item?._raw || {}
    const mode = String(raw?.mode || '').trim().toLowerCase()
    const user = readUser?.() || {}
    const user_id = String(user?.user_id || '')
    let extraQuery = mode.includes('img') ? { mode: 'img' } : null

    if (raw.mode == 'simple') {
      try {
        const res = await inf.app.getUsed.call(raw.app_id, { user_id })
        if (!isSuccess(res)) {
          toast('현재 임베딩 중입니다.')
          return
        }
        let fileInfos = res?.data?.body?.knowledgeDetail_info
        writeOpenAppDoc({ ...fileInfos, appId: res?.data?.body?.app_id })
      } catch (error) {
        console.log(error)
        return
      }
    }

    await updateLogAndGo({ router, item, user_id, extraQuery })
    if (typeof afterGo === 'function') afterGo()
  }

  return { goToApp }
}
