        commonStorage.setItem(KEY, JSON.stringify(Array.isArray(list) ? list : []))
    } catch (e) {}
}

export const writeWorkList = (list) => {
    try {
        commonStorage.setItem(KEY2, JSON.stringify(Array.isArray(list) ? list : []))
    } catch (e) {}
}

/**
 * 저장된 목록 문자열을 배열로 복원한다.
 * 손상된 JSON·비배열·빈 배열이면 null 을 돌려 재조회하도록 한다.
 * @param {*} raw - commonStorage 에 저장된 값
 * @returns {Array|null}
 */
export const parseStoredList = (raw) => {
    if (raw == null) return null
    if (Array.isArray(raw)) return raw.length > 0 ? raw : null
    if (typeof raw !== 'string') return null

    try {
        const parsed = JSON.parse(raw)
        if (!Array.isArray(parsed) || parsed.length === 0) return null
        return parsed
    } catch (e) {
        return null
    }
}

/**
 * 앱 목록 응답에서 특정 serviceCode 의 appList 를 모아 반환한다.
 * serviceCode 표기가 화면마다 달라(myNoteBook / MyNotebook) 대소문자는 무시한다.
 * @param {*} body - appListGet 응답 body
 * @param {string} serviceCode
 * @returns {Array}
 */
export const extractAppList = (body, serviceCode) => {
    if (!Array.isArray(body)) return []

    const target = String(serviceCode || '').toLowerCase()
    return body
        .filter((row) => String(row?.serviceCode || '').toLowerCase() === target)
        .flatMap((row) => (Array.isArray(row?.appList) ? row.appList : []))
}

const buildAppListQs = () => {
    const userId = String(readUser()?.user_id || '')
    return new URLSearchParams({ serviceMenu: MENU_KEY.WORK_TOOLS, user_id: userId }).toString()
}

const fetchAppListByServiceCode = async (serviceCode) => {
    try {
        const res = await inf.athena.appListGet.call(buildAppListQs())
        if (!isSuccess(res)) return []
        return extractAppList(res?.data?.body ?? res?.data, serviceCode)
    } catch (e) {
        return []
    }
}

// 내가 가지고 있는 노트북 리스트
const getMyNoteBookList = async () => {
    const myList = await fetchAppListByServiceCode(SERVICE_CODE_MY_NOTE_BOOK)
    writeMyList(myList)
    return myList
}

// 내가 가지고 있는 업무 도구 리스트
const getWorkToolsList = async () => {
    const myWorkTools = await fetchAppListByServiceCode(SERVICE_CODE_WORK_TOOLS)
    writeWorkList(myWorkTools)
    return myWorkTools
}

export const readMyList = async () => {
    const cached = parseStoredList(commonStorage.get(KEY))
    if (cached) return cached
    return await getMyNoteBookList()
}
